import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateReward } from "../handlers/updateReward";
import type { ApiError } from "../runtime/client";
import type { UpdateGlobalRewardRequest } from "../types/UpdateGlobalRewardRequest";

type Data = Awaited<ReturnType<typeof updateReward>>;
type Vars = UpdateGlobalRewardRequest;

export function useUpdateReward(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateReward(vars),
    ...options,
  });
}
